import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

// Books live in memory and are written to a JSON file on every change.
// Writes go to a temp file first and are then renamed over the real one,
// so a crash mid-write can't leave a half-written books.json behind.
export function createStore(file) {
  let books = load(file);

  function save(next) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    const tmp = `${file}.tmp`;
    fs.writeFileSync(tmp, JSON.stringify(next, null, 2) + '\n');
    fs.renameSync(tmp, file);
    books = next;
  }

  return {
    all() {
      return books;
    },

    get(id) {
      return books.find((b) => b.id === id);
    },

    add({ title, author = '', notes = '' }) {
      const book = {
        id: crypto.randomBytes(6).toString('base64url'),
        title,
        author,
        notes,
        status: 'reading',
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      save([...books, book]);
      return book;
    },

    finish(id) {
      const book = this.get(id);
      if (!book) return undefined;
      if (book.status === 'finished') return book;
      const updated = { ...book, status: 'finished', finishedAt: new Date().toISOString() };
      save(books.map((b) => (b.id === id ? updated : b)));
      return updated;
    },
  };
}

function load(file) {
  let text;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  // Refuse to start on a corrupt file rather than silently overwriting it.
  try {
    const data = JSON.parse(text);
    if (!Array.isArray(data)) throw new Error('expected an array of books');
    return data;
  } catch (err) {
    throw new Error(`Could not read ${file}: ${err.message}`);
  }
}

