const MAX_BODY_BYTES = 64 * 1024;
const LIMITS = { title: 300, author: 300, notes: 10_000 };

export function createApp(store) {
  return async function handle(req, res) {
    const url = new URL(req.url, 'http://localhost');
    const bookMatch = url.pathname.match(/^\/books\/([\w-]+)$/);
    const finishMatch = url.pathname.match(/^\/books\/([\w-]+)\/finish$/);

    try {
      if (url.pathname === '/' && req.method === 'GET') {
        return send(res, 200, homePage(store.all()));
      }

      if (url.pathname === '/books' && req.method === 'POST') {
        const form = await readForm(req);
        const input = {
          title: (form.get('title') ?? '').trim(),
          author: (form.get('author') ?? '').trim(),
          notes: (form.get('notes') ?? '').trim(),
        };
        const error = validate(input);
        if (error) return send(res, 400, homePage(store.all(), { error, input }));
        store.add(input);
        return redirect(res, '/');
      }

      if (bookMatch && req.method === 'GET') {
        const book = store.get(bookMatch[1]);
        if (!book) return send(res, 404, notFoundPage());
        const shareUrl = `http://${req.headers.host ?? 'localhost'}/books/${book.id}`;
        return send(res, 200, bookPage(book, shareUrl));
      }

      if (finishMatch && req.method === 'POST') {
        const form = await readForm(req);
        const book = store.finish(finishMatch[1]);
        if (!book) return send(res, 404, notFoundPage());
        return redirect(res, form.get('from') === 'book' ? `/books/${book.id}` : '/');
      }

      return send(res, 404, notFoundPage());
    } catch (err) {
      if (err.status === 413) return send(res, 413, layout('Too large', '<p>That submission is too large.</p>'));
      console.error(err);
      return send(res, 500, layout('Error', '<p>Something went wrong.</p>'));
    }
  };
}

function validate({ title, author, notes }) {
  if (!title) return 'Please enter a title.';
  if (title.length > LIMITS.title) return `Title must be at most ${LIMITS.title} characters.`;
  if (author.length > LIMITS.author) return `Author must be at most ${LIMITS.author} characters.`;
  if (notes.length > LIMITS.notes) return `Notes must be at most ${LIMITS.notes} characters.`;
  return null;
}

async function readForm(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) {
      throw Object.assign(new Error('Body too large'), { status: 413 });
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

function send(res, status, html) {
  res.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

// --- Views ------------------------------------------------------------------

function esc(value) {
  return String(value)
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function formatDate(iso) {
  return iso ? iso.slice(0, 10) : '';
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${esc(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  h1 a { color: inherit; text-decoration: none; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #666; }
  .error { color: #b00020; }
  form.add label { display: block; margin-top: .75rem; }
  form.add input, form.add textarea { width: 100%; box-sizing: border-box; font: inherit; padding: .3rem; }
  button { font: inherit; cursor: pointer; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: .75rem; border-radius: 4px; }
  input.share { width: 100%; box-sizing: border-box; font: inherit; padding: .3rem; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function finishButton(book, from) {
  return `<form method="post" action="/books/${esc(book.id)}/finish">
    <input type="hidden" name="from" value="${from}">
    <button type="submit">Mark finished</button>
  </form>`;
}

function bookItem(book) {
  const author = book.author ? ` <span class="muted">by ${esc(book.author)}</span>` : '';
  const right = book.status === 'reading'
    ? finishButton(book, 'home')
    : `<span class="muted">${formatDate(book.finishedAt)}</span>`;
  return `<li><span><a href="/books/${esc(book.id)}">${esc(book.title)}</a>${author}</span>${right}</li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="muted">${emptyText}</p>`;
  return `<ul class="books">${books.map(bookItem).join('')}</ul>`;
}

function homePage(books, { error = null, input = {} } = {}) {
  const reading = books
    .filter((b) => b.status === 'reading')
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  return layout('My books', `
<h2>Currently reading</h2>
${bookList(reading, 'Nothing on the go right now.')}

<h2>Finished</h2>
${bookList(finished, 'No finished books yet.')}

<h2>Add a book</h2>
${error ? `<p class="error">${esc(error)}</p>` : ''}
<form class="add" method="post" action="/books">
  <label>Title <input name="title" required maxlength="${LIMITS.title}" value="${esc(input.title ?? '')}"></label>
  <label>Author <input name="author" maxlength="${LIMITS.author}" value="${esc(input.author ?? '')}"></label>
  <label>Notes <textarea name="notes" rows="4" maxlength="${LIMITS.notes}">${esc(input.notes ?? '')}</textarea></label>
  <p><button type="submit">Add book</button></p>
</form>`);
}

function bookPage(book, shareUrl) {
  const status = book.status === 'finished'
    ? `Finished on ${formatDate(book.finishedAt)}`
    : 'Currently reading';
  return layout(book.title, `
<h2>${esc(book.title)}</h2>
<p>${book.author ? `by ${esc(book.author)}` : '<span class="muted">Unknown author</span>'}</p>
<p class="muted">${status}</p>
${book.status === 'reading' ? finishButton(book, 'book') : ''}

<h3>Notes</h3>
${book.notes ? `<div class="notes">${esc(book.notes)}</div>` : '<p class="muted">No notes.</p>'}

<h3>Share</h3>
<input class="share" readonly value="${esc(shareUrl)}" onclick="this.select()">
<p><a href="/">&larr; All books</a></p>`);
}

function notFoundPage() {
  return layout('Not found', '<p>That page doesn’t exist.</p><p><a href="/">&larr; All books</a></p>');
}

