import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import http from 'node:http';
import { createStore } from '../src/store.js';
import { createApp } from '../src/app.js';

let dir, file, server, base;

async function start() {
  server = http.createServer(createApp(createStore(file)));
  await new Promise((resolve) => server.listen(0, resolve));
  base = `http://localhost:${server.address().port}`;
}

async function stop() {
  await new Promise((resolve) => server.close(resolve));
}

function post(pathname, fields) {
  return fetch(base + pathname, {
    method: 'POST',
    body: new URLSearchParams(fields),
    redirect: 'manual',
  });
}

beforeEach(async () => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'books-'));
  file = path.join(dir, 'books.json');
  await start();
});

afterEach(async () => {
  await stop();
  fs.rmSync(dir, { recursive: true, force: true });
});

describe('book tracker', () => {
  it('shows empty lists on a fresh start', async () => {
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Currently reading');
    expect(html).toContain('Nothing on the go right now.');
    expect(html).toContain('No finished books yet.');
  });

  it('adds a book and lists it as currently reading', async () => {
    const res = await post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'Spice!' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe('/');

    const html = await (await fetch(base + '/')).text();
    const reading = html.split('<h2>Finished</h2>')[0];
    expect(reading).toContain('Dune');
    expect(reading).toContain('Frank Herbert');
  });

  it('rejects a book without a title', async () => {
    const res = await post('/books', { title: '   ', author: 'Someone' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Please enter a title.');
    expect(html).toContain('value="Someone"');
    expect(JSON.parse(fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '[]')).toHaveLength(0);
  });

  it('shows a book page with title, author and notes at a shareable URL', async () => {
    await post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'Line one\nLine two' });
    const [book] = JSON.parse(fs.readFileSync(file, 'utf8'));

    const res = await fetch(`${base}/books/${book.id}`);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('<h2>Dune</h2>');
    expect(html).toContain('by Frank Herbert');
    expect(html).toContain('Line one\nLine two');
    expect(html).toContain(`/books/${book.id}"`);
  });

  it('marks a book as finished', async () => {
    await post('/books', { title: 'Dune' });
    const [book] = JSON.parse(fs.readFileSync(file, 'utf8'));

    const res = await post(`/books/${book.id}/finish`, { from: 'book' });
    expect(res.status).toBe(303);
    expect(res.headers.get('location')).toBe(`/books/${book.id}`);

    const html = await (await fetch(base + '/')).text();
    const [reading, finished] = html.split('<h2>Finished</h2>');
    expect(reading).not.toContain('Dune');
    expect(finished).toContain('Dune');
  });

  it('keeps books after a restart', async () => {
    await post('/books', { title: 'Dune' });
    await stop();
    await start();
    const html = await (await fetch(base + '/')).text();
    expect(html).toContain('Dune');
  });

  it('escapes user input', async () => {
    await post('/books', { title: '<script>alert(1)</script>' });
    const html = await (await fetch(base + '/')).text();
    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).toContain('&lt;script&gt;');
  });

  it('returns 404 for unknown books', async () => {
    expect((await fetch(`${base}/books/nope`)).status).toBe(404);
    expect((await post('/books/nope/finish', {})).status).toBe(404);
  });

  it('refuses to start on a corrupt data file instead of overwriting it', () => {
    fs.writeFileSync(file, '{not json');
    expect(() => createStore(file)).toThrow(/Could not read/);
    expect(fs.readFileSync(file, 'utf8')).toBe('{not json');
  });
});

